    // Функция для копирования текста в буфер обмена
    function copyToClipboard(elementId) {
      var element = document.getElementById(elementId);
      var text = element.innerText;

      // Создаем временный элемент textarea для копирования текста
      var textarea = document.createElement('textarea');
      textarea.value = text;
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
      alert('Текст скопирован: ' + text);
  }

  // Функция для управления видимостью VPN boxes
  function toggleVPNBoxes() {
      var boxes = document.querySelectorAll('.box');
      var buttonState = JSON.parse(getCookie('vpnButtonState')) || false;

      boxes.forEach(function (box) {
          var logobg = box.querySelector('.logobg');
          var containsVPN = logobg && logobg.querySelector('.vpn');

          if (containsVPN) {
              box.style.display = buttonState ? 'none' : 'block';
          }
      });

      setCookie('vpnButtonState', !buttonState, 365);
  }

  // Функция для установки cookie
  function setCookie(name, value, days) {
      var expires = '';
      if (days) {
          var date = new Date();
          date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
          expires = '; expires=' + date.toUTCString();
      }
      document.cookie = name + '=' + value + expires + '; path=/';
  }

  // Функция для получения cookie
  function getCookie(name) {
      var nameEQ = name + '=';
      var cookies = document.cookie.split(';');
      for (var i = 0; i < cookies.length; i++) {
          var cookie = cookies[i];
          while (cookie.charAt(0) === ' ') {
              cookie = cookie.substring(1, cookie.length);
          }
          if (cookie.indexOf(nameEQ) === 0) {
              return cookie.substring(nameEQ.length, cookie.length);
          }
      }
      return null;
  }

  // Устанавливаем обработчик события на кнопку
  document.getElementById('button-vpn-filter').addEventListener('click', toggleVPNBoxes);

  // Инициализируем видимость VPN boxes при загрузке страницы
  toggleVPNBoxes();